from __future__ import annotations

import argparse
import json
import sys
from datetime import date
from pathlib import Path
from typing import Any

from django.core.management.base import BaseCommand, CommandError

from trips.services.region_snapshot import import_region_snapshot


class Command(BaseCommand):
    help = "Import a region snapshot JSON file into the local development database."

    def add_arguments(self, parser) -> None:
        parser.add_argument(
            "--input",
            default="-",
            help="Input JSON path. Use '-' to read from stdin.",
        )
        parser.add_argument(
            "--reset",
            action="store_true",
            help="Delete existing regional snapshot data for imported regions first.",
        )
        parser.add_argument(
            "--verification-username",
            default="",
            help="Optional local username that should get a verification trip per region.",
        )
        parser.add_argument(
            "--trip-start",
            default="",
            help="Optional YYYY-MM-DD start date for verification trips.",
        )
        parser.add_argument(
            "--trip-end",
            default="",
            help="Optional YYYY-MM-DD end date for verification trips.",
        )
        parser.add_argument(
            "--allow-non-debug",
            action="store_true",
            help="Allow import when DEBUG=False for an intentional rehearsal.",
        )
        parser.add_argument("--stdin", default=None, help=argparse.SUPPRESS)

    def handle(self, *args, **options) -> None:
        payload = _load_payload(options["input"], stdin=options.get("stdin"))
        counts = import_region_snapshot(
            payload,
            reset=options["reset"],
            verification_username=options["verification_username"],
            trip_start=_parse_date_option(options["trip_start"], "trip-start"),
            trip_end=_parse_date_option(options["trip_end"], "trip-end"),
            allow_non_debug=options["allow_non_debug"],
        )
        self.stdout.write(
            self.style.SUCCESS(
                "Imported region snapshot: "
                + ", ".join(f"{key}={value}" for key, value in counts.items())
            )
        )


def _load_payload(input_path: str, *, stdin: Any) -> dict[str, Any]:
    try:
        if input_path == "-":
            stream = stdin if stdin is not None else sys.stdin
            return json.load(stream)

        with Path(input_path).open(encoding="utf-8") as input_file:
            return json.load(input_file)
    except json.JSONDecodeError as exc:
        raise CommandError(f"Region snapshot JSON is invalid: {exc}") from exc
    except OSError as exc:
        raise CommandError(f"Could not read region snapshot: {exc}") from exc


def _parse_date_option(value: str, label: str) -> date | None:
    if not value:
        return None
    try:
        return date.fromisoformat(value)
    except ValueError as exc:
        raise CommandError(f"--{label} must be YYYY-MM-DD.") from exc

