            "--trip-start",
            default="",
            help="Optional YYYY-MM-DD start date for verification trips.",
        )
        parser.add_argument(
            "--trip-end",
            default="",
            help="Optional YYYY-MM-DD end date for verification trips.",
        )
        parser.add_argument(
            "--allow-non-debug",
            action="store_true",
            help="Allow import when DEBUG=False for an intentional rehearsal.",
        )
        parser.add_argument("--stdin", default=None, help=argparse.SUPPRESS)

